const PAGES = {
  "/": "<!doctype html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"utf-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n    <meta name=\"description\" content=\"ESBE Incorporated is a 501(c)(3) nonprofit that helps veterans get the VA disability benefits they earned \u2014 for free \u2014 and builds free public tools that make government services easier to use.\" />\n    <meta name=\"theme-color\" content=\"#12352d\" />\n    <link rel=\"canonical\" href=\"https://esbeincorporated.org/\" />\n    <link rel=\"icon\" href=\"/favicon.ico\" type=\"image/x-icon\" />\n    <link rel=\"icon\" href=\"/favicon.svg\" type=\"image/svg+xml\" />\n    <link rel=\"apple-touch-icon\" href=\"/apple-touch-icon.png\" />\n    <meta property=\"og:type\" content=\"website\" />\n    <meta property=\"og:site_name\" content=\"ESBE Incorporated\" />\n    <meta property=\"og:title\" content=\"ESBE Incorporated | Veteran support and public-interest work\" />\n    <meta property=\"og:description\" content=\"ESBE Incorporated is a 501(c)(3) nonprofit that helps veterans get the VA disability benefits they earned \u2014 for free \u2014 and builds free public tools that make government services easier to use.\" />\n    <meta property=\"og:url\" content=\"https://esbeincorporated.org/\" />\n    <meta property=\"og:image\" content=\"https://esbeincorporated.org/og.svg\" />\n    <meta property=\"og:image:width\" content=\"1200\" />\n    <meta property=\"og:image:height\" content=\"630\" />\n    <meta name=\"twitter:card\" content=\"summary_large_image\" />\n    <meta name=\"twitter:title\" content=\"ESBE Incorporated | Veteran support and public-interest work\" />\n    <meta name=\"twitter:description\" content=\"ESBE Incorporated is a 501(c)(3) nonprofit that helps veterans get the VA disability benefits they earned \u2014 for free \u2014 and builds free public tools that make government services easier to use.\" />\n    <meta name=\"twitter:image\" content=\"https://esbeincorporated.org/og.svg\" />\n    <link rel=\"stylesheet\" href=\"/styles.css\" />\n    <title>ESBE Incorporated | Veteran support and public-interest work</title>\n    <script type=\"application/ld+json\">{\"@context\":\"https://schema.org\",\"@type\":\"NGO\",\"name\":\"ESBE Incorporated\",\"url\":\"https://esbeincorporated.org/\",\"taxID\":\"87-1218291\",\"email\":\"help@esbeincorporated.org\"}</script>\n  </head>\n  <body>\n    <a class=\"skip-link\" href=\"#main\">Skip to content</a>\n    <header class=\"site-header\">\n      <a class=\"wordmark\" href=\"/\" aria-label=\"ESBE Incorporated home\">ESBE <span>INC.</span></a>\n      <nav aria-label=\"Primary navigation\">\n        <a href=\"/about\">About</a><a href=\"/programs\">Programs</a><a href=\"/transparency\">Transparency</a><a href=\"/support\">Support</a><a href=\"/contact\">Contact</a>\n      </nav>\n      <a class=\"header-cta\" href=\"https://aivaclaims.com\" rel=\"noreferrer\">Visit AIVA Claims <span aria-hidden=\"true\">\u2197</span></a>\n    </header>\n    <main id=\"main\">\n<section class=\"hero\" aria-labelledby=\"hero-title\">\n        <p class=\"eyebrow\">501(C)(3) NONPROFIT \u2022 VETERANS \u2022 PUBLIC INTEREST</p>\n        <div class=\"hero-grid\">\n          <h1 id=\"hero-title\">ESBE Incorporated helps veterans get the VA disability benefits they earned \u2014 for free.</h1>\n          <div class=\"hero-copy\"><p>We are a 501(c)(3) nonprofit founded by a disabled veteran. Our flagship program, AIVA Claims, provides free one-on-one assistance to veterans working to understand and prepare VA disability claims. We also build free public tools that make government services easier for everyone to use.</p></div>\n        </div>\n        <div class=\"hero-rule\" aria-hidden=\"true\"></div>\n      </section>\n      <section class=\"statement\" aria-labelledby=\"what-title\">\n        <div><p class=\"section-mark\">01</p></div>\n        <div><p class=\"eyebrow\">WHAT WE DO</p><h2 id=\"what-title\">Two lines of work, one purpose.</h2></div>\n        <div>\n          <p class=\"body-large\"><strong>For veterans:</strong> AIVA Claims offers free, personalized help preparing VA disability claims \u2014 understanding eligibility, gathering evidence, and navigating the VA process. No fees, no strings.</p>\n          <p class=\"body-large\"><strong>For the public:</strong> We build free tools like ImproveBayArea (Bay Area 311 reporting), Hospital Ledger (hospital price transparency), and the Treasure Island power outage tracker \u2014 practical resources that make public systems more understandable.</p>\n          <p class=\"body-large\"><strong>How we\u2019re funded:</strong> ESBE Incorporated is a donor-supported 501(c)(3) nonprofit (EIN 87-1218291). We are independent and do not speak for or act on behalf of any government agency.</p>\n        </div>\n      </section>\n      <section class=\"statement\" aria-labelledby=\"mission-title\">\n        <div><p class=\"section-mark\">02</p></div>\n        <div><p class=\"eyebrow\">OUR MISSION</p><h2 id=\"mission-title\">Our mission</h2></div>\n        <div><p class=\"body-large\">To ensure veterans can access the disability benefits they earned through free, expert claims assistance \u2014 and to strengthen public access to government services through clear information and accessible technology.</p></div>\n      </section>\n      <section class=\"programs\" id=\"programs\" aria-labelledby=\"programs-title\">\n        <div class=\"section-heading\"><div><p class=\"section-mark\">03</p></div><div><p class=\"eyebrow\">PUBLIC-INTEREST WORK</p><h2 id=\"programs-title\">Practical help for veterans and public service.</h2></div></div>\n        <div class=\"program-grid\">\n          <article class=\"program-card\">\n            <div class=\"program-top\"><p class=\"program-kicker\">VETERAN SUPPORT</p><span>01</span></div>\n            <div class=\"program-content\"><div><h3>AIVA Claims</h3><p>Free assistance for veterans working to understand and prepare VA disability claims. <a href=\"/programs\" style=\"color:inherit\">Learn more about our programs \u2192</a></p></div><a class=\"button light\" href=\"https://aivaclaims.com\" rel=\"noreferrer\">Visit AIVA Claims <span aria-hidden=\"true\">\u2197</span></a></div>\n          </article>\n          <article class=\"program-card public-interest-card\">\n            <div class=\"program-top\"><p class=\"program-kicker\">CIVIC ACCESS</p><span>02</span></div>\n            <div class=\"program-content\"><div><h3>Public-interest services</h3><p>Accessible technology and plain-language information that help people understand and use government-facing services.</p></div></div>\n          </article>\n        </div>\n        <section class=\"civic-projects\" aria-labelledby=\"civic-projects-title\">\n          <div class=\"civic-projects-heading\"><div><p class=\"program-kicker\">SELECTED CIVIC PROJECTS</p><h3 id=\"civic-projects-title\">Public tools for public systems.</h3></div><p>These independent public projects make government-facing information and reporting paths more understandable. They do not represent or act for a government agency.</p></div>\n          <div class=\"civic-project-grid\">\n            <article class=\"civic-project\"><p class=\"civic-project-meta\">FEDERAL TRANSPARENCY \u00b7 LIVE</p><h4>Hospital Ledger</h4><p>A public-good resource for exploring hospital price files published under federal transparency requirements.</p><a href=\"https://hospitalledger.com\" rel=\"noreferrer\">Visit Hospital Ledger <span aria-hidden=\"true\">\u2197</span></a></article>\n            <article class=\"civic-project\"><p class=\"civic-project-meta\">SAN FRANCISCO PERMITS \u00b7 PROTOTYPE</p><h4>SF Permit Navigator</h4><p>A plain-language permit-path prototype that identifies where an official city system is required.</p><a href=\"https://sf-permit-detector.barkleesanders.workers.dev\" rel=\"noreferrer\">Visit SF Permit Navigator <span aria-hidden=\"true\">\u2197</span></a></article>\n            <article class=\"civic-project\"><p class=\"civic-project-meta\">BAY AREA 311 \u00b7 LIVE</p><h4>ImproveBayArea</h4><p>One public reporting form that routes Bay Area requests to the appropriate official 311 service.</p><a href=\"https://improvebayarea.com\" rel=\"noreferrer\">Visit ImproveBayArea <span aria-hidden=\"true\">\u2197</span></a></article>\n            <article class=\"civic-project\"><p class=\"civic-project-meta\">NATIONAL PARKS \u00b7 LIVE</p><h4>NPS Report</h4><p>A public tool for reporting maintenance and safety concerns through National Park Service contact paths.</p><a href=\"https://nps-report.barkleesanders.workers.dev\" rel=\"noreferrer\">Visit NPS Report <span aria-hidden=\"true\">\u2197</span></a></article>\n            <article class=\"civic-project\"><p class=\"civic-project-meta\">SF AFFORDABLE HOUSING \u00b7 PROTOTYPE</p><h4>SF Income Verify</h4><p>A privacy-first income-verification prototype for San Francisco affordable housing. Not affiliated with MOHCD.</p><a href=\"https://sf-income-verify.barkleesanders.workers.dev/#how-it-works\" rel=\"noreferrer\">Visit SF Income Verify <span aria-hidden=\"true\">\u2197</span></a></article>\n            <article class=\"civic-project\"><p class=\"civic-project-meta\">PUBLIC INFRASTRUCTURE \u00b7 LIVE</p><h4>Treasure Island Power</h4><p>A public outage tracker documenting Treasure Island power failures and related accountability work.</p><a href=\"https://www.treasureislandsfpoweroutages.com\" rel=\"noreferrer\">Visit Treasure Island Power <span aria-hidden=\"true\">\u2197</span></a></article>\n          </div>\n        </section>\n        <div class=\"project-row\"><p>Independent infrastructure</p><a href=\"https://esbe.tech\" rel=\"noreferrer\"><span>ESBE Tech</span><span aria-hidden=\"true\">\u2197</span></a><a href=\"https://barkleesanders.com\" rel=\"noreferrer\"><span>Projects by Barklee Sanders</span><span aria-hidden=\"true\">\u2197</span></a></div>\n      </section>\n      <section class=\"transparency\" aria-labelledby=\"transparency-title\">\n        <div class=\"section-heading\"><div><p class=\"section-mark\">04</p></div><div><p class=\"eyebrow\">TRANSPARENCY</p><h2 id=\"transparency-title\">Clear identity. Clear accountability.</h2></div></div>\n        <dl class=\"facts\"><div><dt>Organization</dt><dd>ESBE Incorporated</dd></div><div><dt>Federal tax ID</dt><dd>87-1218291</dd></div><div><dt>Federal status</dt><dd>501(c)(3) nonprofit organization</dd></div><div><dt>California charity registration</dt><dd>CT0403243</dd></div><div><dt>Public purpose</dt><dd>Veteran support and public-interest access to government-facing services.</dd></div><div><dt>Government relationship</dt><dd>Independent nonprofit; not a government agency.</dd></div></dl>\n        <div class=\"transparency-links\"><a href=\"/transparency\">Read our transparency page \u2192</a></div>\n      </section>\n      <section class=\"contact\" aria-labelledby=\"contact-title\">\n        <div><p class=\"section-mark\">05</p></div>\n        <div><p class=\"eyebrow\">PUBLIC CONTACT</p><h2 id=\"contact-title\">Contact ESBE Incorporated.</h2><p class=\"contact-copy\">For public inquiries, governance requests, and nonprofit correspondence, reach us by email, phone, or mail.</p><div class=\"contact-details\"><a class=\"contact-email\" href=\"mailto:help@esbeincorporated.org\">help@esbeincorporated.org <span aria-hidden=\"true\">\u2197</span></a><a class=\"contact-phone\" href=\"tel:+18027153723\">(802) 715-3723</a><address>1070 Bridgeview Way #1010<br />San Francisco, CA 94158</address></div></div>\n      </section>\n    </main>\n    <footer><div class=\"footer-brand\">ESBE INCORPORATED</div><p>ESBE Incorporated is a 501(c)(3) nonprofit organization, EIN 87-1218291. AIVA Claims is a charitable program of ESBE Incorporated. ESBE Tech is a separate for-profit technology company. ESBE Incorporated is not affiliated with or endorsed by the U.S. Department of Veterans Affairs.</p><div><span>\u00a9 2026 ESBE Incorporated</span><span><a href=\"/privacy\">Privacy</a> \u00b7 <a href=\"/contact\">Contact</a> \u00b7 <a href=\"/support\">Support</a></span></div></footer>\n    <script type=\"module\" src=\"/webmcp.js\"></script>\n  </body>\n</html>",
  "/about": "<!doctype html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"utf-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n    <meta name=\"description\" content=\"ESBE Incorporated is a 501(c)(3) nonprofit founded by a disabled veteran to provide free VA disability claims assistance and build public-interest tools.\" />\n    <meta name=\"theme-color\" content=\"#12352d\" />\n    <link rel=\"canonical\" href=\"https://esbeincorporated.org/about\" />\n    <link rel=\"icon\" href=\"/favicon.ico\" type=\"image/x-icon\" />\n    <link rel=\"icon\" href=\"/favicon.svg\" type=\"image/svg+xml\" />\n    <link rel=\"apple-touch-icon\" href=\"/apple-touch-icon.png\" />\n    <meta property=\"og:type\" content=\"website\" />\n    <meta property=\"og:site_name\" content=\"ESBE Incorporated\" />\n    <meta property=\"og:title\" content=\"About ESBE Incorporated | Who we are\" />\n    <meta property=\"og:description\" content=\"ESBE Incorporated is a 501(c)(3) nonprofit founded by a disabled veteran to provide free VA disability claims assistance and build public-interest tools.\" />\n    <meta property=\"og:url\" content=\"https://esbeincorporated.org/about\" />\n    <meta property=\"og:image\" content=\"https://esbeincorporated.org/og.svg\" />\n    <meta property=\"og:image:width\" content=\"1200\" />\n    <meta property=\"og:image:height\" content=\"630\" />\n    <meta name=\"twitter:card\" content=\"summary_large_image\" />\n    <meta name=\"twitter:title\" content=\"About ESBE Incorporated | Who we are\" />\n    <meta name=\"twitter:description\" content=\"ESBE Incorporated is a 501(c)(3) nonprofit founded by a disabled veteran to provide free VA disability claims assistance and build public-interest tools.\" />\n    <meta name=\"twitter:image\" content=\"https://esbeincorporated.org/og.svg\" />\n    <link rel=\"stylesheet\" href=\"/styles.css\" />\n    <title>About ESBE Incorporated | Who we are</title>\n    <script type=\"application/ld+json\">{\"@context\":\"https://schema.org\",\"@type\":\"NGO\",\"name\":\"ESBE Incorporated\",\"url\":\"https://esbeincorporated.org/\",\"taxID\":\"87-1218291\",\"email\":\"help@esbeincorporated.org\"}</script>\n  </head>\n  <body>\n    <a class=\"skip-link\" href=\"#main\">Skip to content</a>\n    <header class=\"site-header\">\n      <a class=\"wordmark\" href=\"/\" aria-label=\"ESBE Incorporated home\">ESBE <span>INC.</span></a>\n      <nav aria-label=\"Primary navigation\">\n        <a href=\"/about\">About</a><a href=\"/programs\">Programs</a><a href=\"/transparency\">Transparency</a><a href=\"/support\">Support</a><a href=\"/contact\">Contact</a>\n      </nav>\n      <a class=\"header-cta\" href=\"https://aivaclaims.com\" rel=\"noreferrer\">Visit AIVA Claims <span aria-hidden=\"true\">\u2197</span></a>\n    </header>\n    <main id=\"main\">\n<section class=\"hero\" aria-labelledby=\"hero-title\">\n        <p class=\"eyebrow\">ABOUT ESBE INCORPORATED</p>\n        <div class=\"hero-grid\">\n          <h1 id=\"hero-title\">A nonprofit built by a veteran who got tired of watching the system fail veterans.</h1>\n          <div class=\"hero-copy\"><p>ESBE Incorporated is a 501(c)(3) nonprofit organization founded by Barklee Sanders, a disabled veteran who experienced firsthand how difficult the VA disability claims process can be \u2014 and decided to do something about it.</p></div>\n        </div>\n        <div class=\"hero-rule\" aria-hidden=\"true\"></div>\n      </section><section class=\"statement\" aria-labelledby=\"s1-title\">\n        <div><p class=\"section-mark\">01</p></div>\n        <div><p class=\"eyebrow\">WHO WE ARE</p><h2 id=\"s1-title\">Filling the gap between veterans and the benefits they earned.</h2></div>\n        <div><p class=\"body-large\">After navigating his own claims, Barklee saw a gap: veterans who need help understanding the VA system often can\u2019t afford professional assistance, and free resources are scattered, confusing, or incomplete. Some veterans pay claims agents a percentage of their back pay or monthly benefits \u2014 money that should stay with the veteran and their family. Others try to go it alone and miss deadlines, submit incomplete evidence, or accept ratings that don\u2019t reflect their conditions.</p><p class=\"body-large\">ESBE Incorporated was created to fill that gap \u2014 starting with direct, free claims assistance and growing into broader public-interest work. Our flagship program, AIVA Claims, gives veterans free one-on-one help preparing VA disability claims: understanding eligibility, gathering the right evidence, and navigating each stage of the process. Alongside it, we build free public tools \u2014 from Bay Area 311 reporting to hospital price transparency \u2014 that make government-facing systems more understandable for everyone.</p></div>\n      </section><section class=\"statement\" aria-labelledby=\"s2-title\">\n        <div><p class=\"section-mark\">02</p></div>\n        <div><p class=\"eyebrow\">WHAT WE BELIEVE</p><h2 id=\"s2-title\">Three convictions guide everything we do.</h2></div>\n        <div><p class=\"body-large\">Veterans earned their benefits. The claims process should not be a barrier to receiving them. A veteran\u2019s service-connected conditions deserve a fair, complete evaluation \u2014 and paperwork should never be the reason someone goes without.</p><p class=\"body-large\">Expert help should be free. No veteran should have to pay a percentage of their back pay or monthly benefits to get assistance they need. Our programs are donor-supported so that cost is never the reason a veteran goes without help.</p><p class=\"body-large\">Government systems should be understandable. When the stakes are high \u2014 disability benefits, housing, public safety \u2014 people deserve clear information and working tools. We build plain-language resources and practical technology that help people navigate systems that were not designed with them in mind.</p></div>\n      </section><section class=\"statement\" aria-labelledby=\"s3-title\">\n        <div><p class=\"section-mark\">03</p></div>\n        <div><p class=\"eyebrow\">WHAT WE DO</p><h2 id=\"s3-title\">Two lines of work.</h2></div>\n        <div><p class=\"body-large\">AIVA Claims \u2014 our flagship program providing free VA disability claims assistance to veterans nationwide. One-on-one help understanding eligibility and rating criteria, identifying supporting medical evidence, preparing for Compensation &amp; Pension examinations, understanding the claims timeline, and navigating supplemental claims and appeals.</p><p class=\"body-large\">Civic access projects \u2014 free public tools that help people understand and use government-facing services: ImproveBayArea for Bay Area 311 reporting, Hospital Ledger for hospital price transparency, the Treasure Island power outage tracker, the SF Permit Navigator, NPS Report for national park concerns, and SF Income Verify for affordable-housing income verification. These are independent public resources; they do not represent or act on behalf of any government agency.</p></div>\n      </section><section class=\"statement\" aria-labelledby=\"s4-title\">\n        <div><p class=\"section-mark\">04</p></div>\n        <div><p class=\"eyebrow\">OUR INDEPENDENCE</p><h2 id=\"s4-title\">Independent, always.</h2></div>\n        <div><p class=\"body-large\">ESBE Incorporated is an independent nonprofit organization. We are not a government agency, we do not represent the Department of Veterans Affairs or any other government body, and our tools and guidance do not constitute legal advice. Our accountability is to our mission, the veterans we serve, and our donors.</p></div>\n      </section>\n    </main>\n    <footer><div class=\"footer-brand\">ESBE INCORPORATED</div><p>ESBE Incorporated is a 501(c)(3) nonprofit organization, EIN 87-1218291. AIVA Claims is a charitable program of ESBE Incorporated. ESBE Tech is a separate for-profit technology company. ESBE Incorporated is not affiliated with or endorsed by the U.S. Department of Veterans Affairs.</p><div><span>\u00a9 2026 ESBE Incorporated</span><span><a href=\"/privacy\">Privacy</a> \u00b7 <a href=\"/contact\">Contact</a> \u00b7 <a href=\"/support\">Support</a></span></div></footer>\n    <script type=\"module\" src=\"/webmcp.js\"></script>\n  </body>\n</html>",
  "/programs": "<!doctype html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"utf-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n    <meta name=\"description\" content=\"AIVA Claims provides free VA disability claims assistance to veterans nationwide. ESBE Incorporated also builds free civic access tools like ImproveBayArea and Hospital Ledger.\" />\n    <meta name=\"theme-color\" content=\"#12352d\" />\n    <link rel=\"canonical\" href=\"https://esbeincorporated.org/programs\" />\n    <link rel=\"icon\" href=\"/favicon.ico\" type=\"image/x-icon\" />\n    <link rel=\"icon\" href=\"/favicon.svg\" type=\"image/svg+xml\" />\n    <link rel=\"apple-touch-icon\" href=\"/apple-touch-icon.png\" />\n    <meta property=\"og:type\" content=\"website\" />\n    <meta property=\"og:site_name\" content=\"ESBE Incorporated\" />\n    <meta property=\"og:title\" content=\"Our Programs | AIVA Claims & Civic Access Projects\" />\n    <meta property=\"og:description\" content=\"AIVA Claims provides free VA disability claims assistance to veterans nationwide. ESBE Incorporated also builds free civic access tools like ImproveBayArea and Hospital Ledger.\" />\n    <meta property=\"og:url\" content=\"https://esbeincorporated.org/programs\" />\n    <meta property=\"og:image\" content=\"https://esbeincorporated.org/og.svg\" />\n    <meta property=\"og:image:width\" content=\"1200\" />\n    <meta property=\"og:image:height\" content=\"630\" />\n    <meta name=\"twitter:card\" content=\"summary_large_image\" />\n    <meta name=\"twitter:title\" content=\"Our Programs | AIVA Claims & Civic Access Projects\" />\n    <meta name=\"twitter:description\" content=\"AIVA Claims provides free VA disability claims assistance to veterans nationwide. ESBE Incorporated also builds free civic access tools like ImproveBayArea and Hospital Ledger.\" />\n    <meta name=\"twitter:image\" content=\"https://esbeincorporated.org/og.svg\" />\n    <link rel=\"stylesheet\" href=\"/styles.css\" />\n    <title>Our Programs | AIVA Claims & Civic Access Projects</title>\n    <script type=\"application/ld+json\">{\"@context\":\"https://schema.org\",\"@type\":\"NGO\",\"name\":\"ESBE Incorporated\",\"url\":\"https://esbeincorporated.org/\",\"taxID\":\"87-1218291\",\"email\":\"help@esbeincorporated.org\"}</script>\n  </head>\n  <body>\n    <a class=\"skip-link\" href=\"#main\">Skip to content</a>\n    <header class=\"site-header\">\n      <a class=\"wordmark\" href=\"/\" aria-label=\"ESBE Incorporated home\">ESBE <span>INC.</span></a>\n      <nav aria-label=\"Primary navigation\">\n        <a href=\"/about\">About</a><a href=\"/programs\">Programs</a><a href=\"/transparency\">Transparency</a><a href=\"/support\">Support</a><a href=\"/contact\">Contact</a>\n      </nav>\n      <a class=\"header-cta\" href=\"https://aivaclaims.com\" rel=\"noreferrer\">Visit AIVA Claims <span aria-hidden=\"true\">\u2197</span></a>\n    </header>\n    <main id=\"main\">\n<section class=\"hero\" aria-labelledby=\"hero-title\">\n        <p class=\"eyebrow\">OUR PROGRAMS</p>\n        <div class=\"hero-grid\">\n          <h1 id=\"hero-title\">Free help for veterans. Free tools for the public.</h1>\n          <div class=\"hero-copy\"><p>ESBE Incorporated runs two lines of work: AIVA Claims, our flagship program providing free VA disability claims assistance to veterans nationwide, and a family of civic access projects \u2014 free public tools that make government-facing services easier to understand and use.</p></div>\n        </div>\n        <div class=\"hero-rule\" aria-hidden=\"true\"></div>\n      </section><section class=\"statement\" aria-labelledby=\"s1-title\">\n        <div><p class=\"section-mark\">01</p></div>\n        <div><p class=\"eyebrow\">AIVA CLAIMS</p><h2 id=\"s1-title\">Free VA disability claims assistance.</h2></div>\n        <div><p class=\"body-large\">The VA disability claims process is complex. Veterans must understand medical evidence requirements, VA rating criteria, filing deadlines, and appeal options \u2014 often while dealing with the very conditions they\u2019re claiming for. Professional help exists but typically costs money many veterans don\u2019t have, and some services take a cut of the veteran\u2019s own benefits.</p><p class=\"body-large\">AIVA Claims exists to change that equation. We provide free, one-on-one assistance to veterans preparing VA disability claims. Our help includes understanding VA disability eligibility and rating criteria; identifying what medical evidence supports a claim; preparing for Compensation &amp; Pension (C&amp;P) examinations; understanding the claims timeline and what to expect at each stage; and guidance on supplemental claims and appeals if a claim is denied.</p><p class=\"body-large\">Who it serves: veterans nationwide who need help with VA disability claims. Cost: free. AIVA Claims is a donor-funded program of ESBE Incorporated. We do not charge fees, take a percentage of benefits, or require payment of any kind.</p><p class=\"body-large\">How to start: email help@esbeincorporated.org with the subject line \u201cClaims Help,\u201d call (802) 715-3723, or visit aivaclaims.com.</p></div>\n      </section><section class=\"programs\" aria-labelledby=\"civic-title\">\n        <div class=\"section-heading\"><div><p class=\"section-mark\">02</p></div><div><p class=\"eyebrow\">CIVIC ACCESS PROJECTS</p><h2 id=\"civic-title\">Free public tools for public systems.</h2></div></div>\n        <div class=\"civic-project-grid\">\n          <article class=\"civic-project\"><p class=\"civic-project-meta\">BAY AREA 311 \u00b7 LIVE</p><h4>ImproveBayArea</h4><p>One public reporting form that routes Bay Area requests to the appropriate official 311 service.</p><a href=\"https://improvebayarea.com\" rel=\"noreferrer\">Visit ImproveBayArea <span aria-hidden=\"true\">\u2197</span></a></article>\n          <article class=\"civic-project\"><p class=\"civic-project-meta\">FEDERAL TRANSPARENCY \u00b7 LIVE</p><h4>Hospital Ledger</h4><p>A public-good resource for exploring hospital price files published under federal transparency requirements.</p><a href=\"https://hospitalledger.com\" rel=\"noreferrer\">Visit Hospital Ledger <span aria-hidden=\"true\">\u2197</span></a></article>\n          <article class=\"civic-project\"><p class=\"civic-project-meta\">PUBLIC INFRASTRUCTURE \u00b7 LIVE</p><h4>Treasure Island Power Tracker</h4><p>Documents Treasure Island power failures and related accountability work.</p><a href=\"https://www.treasureislandsfpoweroutages.com\" rel=\"noreferrer\">Visit the tracker <span aria-hidden=\"true\">\u2197</span></a></article>\n          <article class=\"civic-project\"><p class=\"civic-project-meta\">SAN FRANCISCO PERMITS \u00b7 PROTOTYPE</p><h4>SF Permit Navigator</h4><p>A plain-language prototype helping San Franciscans understand permit requirements.</p><a href=\"https://sf-permit-detector.barkleesanders.workers.dev\" rel=\"noreferrer\">Visit the prototype <span aria-hidden=\"true\">\u2197</span></a></article>\n          <article class=\"civic-project\"><p class=\"civic-project-meta\">NATIONAL PARKS \u00b7 LIVE</p><h4>NPS Report</h4><p>A tool for reporting maintenance and safety concerns through National Park Service contact paths.</p><a href=\"https://nps-report.barkleesanders.workers.dev\" rel=\"noreferrer\">Visit NPS Report <span aria-hidden=\"true\">\u2197</span></a></article>\n          <article class=\"civic-project\"><p class=\"civic-project-meta\">SF AFFORDABLE HOUSING \u00b7 PROTOTYPE</p><h4>SF Income Verify</h4><p>A privacy-first income-verification prototype for San Francisco affordable housing. Not affiliated with MOHCD.</p><a href=\"https://sf-income-verify.barkleesanders.workers.dev/#how-it-works\" rel=\"noreferrer\">Visit the prototype <span aria-hidden=\"true\">\u2197</span></a></article>\n        </div>\n        <p style=\"color:oklch(0.82 0.02 120);max-width:44rem;margin-top:var(--space-xl)\">These projects are independent public resources built and maintained by ESBE Incorporated. They do not represent or act on behalf of any government agency.</p>\n      </section>\n    </main>\n    <footer><div class=\"footer-brand\">ESBE INCORPORATED</div><p>ESBE Incorporated is a 501(c)(3) nonprofit organization, EIN 87-1218291. AIVA Claims is a charitable program of ESBE Incorporated. ESBE Tech is a separate for-profit technology company. ESBE Incorporated is not affiliated with or endorsed by the U.S. Department of Veterans Affairs.</p><div><span>\u00a9 2026 ESBE Incorporated</span><span><a href=\"/privacy\">Privacy</a> \u00b7 <a href=\"/contact\">Contact</a> \u00b7 <a href=\"/support\">Support</a></span></div></footer>\n    <script type=\"module\" src=\"/webmcp.js\"></script>\n  </body>\n</html>",
  "/transparency": "<!doctype html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"utf-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n    <meta name=\"description\" content=\"ESBE Incorporated is a 501(c)(3) nonprofit (EIN 87-1218291), registered with the California Attorney General (CT0403243). Our status, finances, and governance, documented.\" />\n    <meta name=\"theme-color\" content=\"#12352d\" />\n    <link rel=\"canonical\" href=\"https://esbeincorporated.org/transparency\" />\n    <link rel=\"icon\" href=\"/favicon.ico\" type=\"image/x-icon\" />\n    <link rel=\"icon\" href=\"/favicon.svg\" type=\"image/svg+xml\" />\n    <link rel=\"apple-touch-icon\" href=\"/apple-touch-icon.png\" />\n    <meta property=\"og:type\" content=\"website\" />\n    <meta property=\"og:site_name\" content=\"ESBE Incorporated\" />\n    <meta property=\"og:title\" content=\"Transparency & Governance | ESBE Incorporated\" />\n    <meta property=\"og:description\" content=\"ESBE Incorporated is a 501(c)(3) nonprofit (EIN 87-1218291), registered with the California Attorney General (CT0403243). Our status, finances, and governance, documented.\" />\n    <meta property=\"og:url\" content=\"https://esbeincorporated.org/transparency\" />\n    <meta property=\"og:image\" content=\"https://esbeincorporated.org/og.svg\" />\n    <meta property=\"og:image:width\" content=\"1200\" />\n    <meta property=\"og:image:height\" content=\"630\" />\n    <meta name=\"twitter:card\" content=\"summary_large_image\" />\n    <meta name=\"twitter:title\" content=\"Transparency & Governance | ESBE Incorporated\" />\n    <meta name=\"twitter:description\" content=\"ESBE Incorporated is a 501(c)(3) nonprofit (EIN 87-1218291), registered with the California Attorney General (CT0403243). Our status, finances, and governance, documented.\" />\n    <meta name=\"twitter:image\" content=\"https://esbeincorporated.org/og.svg\" />\n    <link rel=\"stylesheet\" href=\"/styles.css\" />\n    <title>Transparency & Governance | ESBE Incorporated</title>\n    <script type=\"application/ld+json\">{\"@context\":\"https://schema.org\",\"@type\":\"NGO\",\"name\":\"ESBE Incorporated\",\"url\":\"https://esbeincorporated.org/\",\"taxID\":\"87-1218291\",\"email\":\"help@esbeincorporated.org\"}</script>\n  </head>\n  <body>\n    <a class=\"skip-link\" href=\"#main\">Skip to content</a>\n    <header class=\"site-header\">\n      <a class=\"wordmark\" href=\"/\" aria-label=\"ESBE Incorporated home\">ESBE <span>INC.</span></a>\n      <nav aria-label=\"Primary navigation\">\n        <a href=\"/about\">About</a><a href=\"/programs\">Programs</a><a href=\"/transparency\">Transparency</a><a href=\"/support\">Support</a><a href=\"/contact\">Contact</a>\n      </nav>\n      <a class=\"header-cta\" href=\"https://aivaclaims.com\" rel=\"noreferrer\">Visit AIVA Claims <span aria-hidden=\"true\">\u2197</span></a>\n    </header>\n    <main id=\"main\">\n<section class=\"hero\" aria-labelledby=\"hero-title\">\n        <p class=\"eyebrow\">TRANSPARENCY & GOVERNANCE</p>\n        <div class=\"hero-grid\">\n          <h1 id=\"hero-title\">A nonprofit should be easy to check on. Here\u2019s everything.</h1>\n          <div class=\"hero-copy\"><p>ESBE Incorporated is a 501(c)(3) nonprofit organization recognized by the Internal Revenue Service. This page documents our nonprofit status, our finances, and how we govern ourselves \u2014 because an organization that asks for public trust should make itself easy to verify.</p></div>\n        </div>\n        <div class=\"hero-rule\" aria-hidden=\"true\"></div>\n      </section><section class=\"statement\" aria-labelledby=\"s1-title\">\n        <div><p class=\"section-mark\">01</p></div>\n        <div><p class=\"eyebrow\">OUR NONPROFIT STATUS</p><h2 id=\"s1-title\">Verified facts about who we are.</h2></div>\n        <div><p class=\"body-large\">Legal name: ESBE Incorporated. Federal Tax ID (EIN): 87-1218291. IRS ruling date: May 1, 2026 \u2014 the date the IRS recognized ESBE Incorporated as a 501(c)(3) tax-exempt organization. You can read the IRS determination letter and confirm our exempt status in the IRS Tax Exempt Organization Search, both linked below.</p><p class=\"body-large\">We are also registered with the California Attorney General\u2019s Registry of Charities and Fundraisers, Registration No. CT0403243, issued October 2, 2026. California requires charities that solicit donations in the state to register, and our registration is current.</p></div>\n      </section><section class=\"statement\" aria-labelledby=\"s2-title\">\n        <div><p class=\"section-mark\">02</p></div>\n        <div><p class=\"eyebrow\">FINANCIAL TRANSPARENCY</p><h2 id=\"s2-title\">Where the money goes.</h2></div>\n        <div><p class=\"body-large\">ESBE Incorporated is donor-supported. Donations fund the time, tools, and technology behind AIVA Claims and our civic access projects. We do not charge the veterans we serve, and we do not sell data.</p><p class=\"body-large\">As a recently recognized nonprofit, we have not yet completed our first full filing year. Our annual Form 990 and financial summaries will be published on this page as they become available. In the meantime, questions about our finances are welcome at help@esbeincorporated.org.</p></div>\n      </section><section class=\"statement\" aria-labelledby=\"s3-title\">\n        <div><p class=\"section-mark\">03</p></div>\n        <div><p class=\"eyebrow\">GOVERNANCE</p><h2 id=\"s3-title\">Who runs ESBE Incorporated.</h2></div>\n        <div><p class=\"body-large\">ESBE Incorporated was founded by Barklee Sanders, a disabled veteran, and is led by its founder. We keep our governance simple and our decision-making close to the mission: free help for veterans, and public tools that make government systems more understandable.</p><p class=\"body-large\">For questions about our nonprofit status, finances, or governance, contact help@esbeincorporated.org with the subject line \u201cGovernance.\u201d</p></div>\n      </section><section class=\"statement\" aria-labelledby=\"s4-title\">\n        <div><p class=\"section-mark\">04</p></div>\n        <div><p class=\"eyebrow\">INDEPENDENCE</p><h2 id=\"s4-title\">Independent of government.</h2></div>\n        <div><p class=\"body-large\">ESBE Incorporated is an independent nonprofit. We do not speak for, act on behalf of, or receive direction from any government agency, including the Department of Veterans Affairs. Our programs serve veterans and the public; our accountability is to our mission and our donors.</p></div>\n      </section><section class=\"statement\" aria-labelledby=\"docs-title\">\n        <div><p class=\"section-mark\">05</p></div>\n        <div><p class=\"eyebrow\">DOCUMENTS</p><h2 id=\"docs-title\">Verify us yourself.</h2></div>\n        <div>\n          <p class=\"body-large\"><a href=\"https://apps.irs.gov/pub/epostcard/dl/FinalLetter_87-1218291_ESBEINCORPORATED_05012026_v1.0.pdf\" rel=\"noreferrer\">Read the IRS determination letter \u2197</a></p>\n          <p class=\"body-large\"><a href=\"https://apps.irs.gov/app/eos/\" rel=\"noreferrer\">Search the IRS Tax Exempt Organization Search \u2197</a></p>\n          <p class=\"body-large\"><a href=\"mailto:help@esbeincorporated.org?subject=ESBE%20Incorporated%20transparency%20request\">Request governance or filing information</a></p>\n        </div>\n      </section>\n    </main>\n    <footer><div class=\"footer-brand\">ESBE INCORPORATED</div><p>ESBE Incorporated is a 501(c)(3) nonprofit organization, EIN 87-1218291. AIVA Claims is a charitable program of ESBE Incorporated. ESBE Tech is a separate for-profit technology company. ESBE Incorporated is not affiliated with or endorsed by the U.S. Department of Veterans Affairs.</p><div><span>\u00a9 2026 ESBE Incorporated</span><span><a href=\"/privacy\">Privacy</a> \u00b7 <a href=\"/contact\">Contact</a> \u00b7 <a href=\"/support\">Support</a></span></div></footer>\n    <script type=\"module\" src=\"/webmcp.js\"></script>\n  </body>\n</html>",
  "/privacy": "<!doctype html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"utf-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n    <meta name=\"description\" content=\"The ESBE Incorporated privacy policy: what we collect through esbeincorporated.org, how we use it, and your rights. Effective October 6, 2026.\" />\n    <meta name=\"theme-color\" content=\"#12352d\" />\n    <link rel=\"canonical\" href=\"https://esbeincorporated.org/privacy\" />\n    <link rel=\"icon\" href=\"/favicon.ico\" type=\"image/x-icon\" />\n    <link rel=\"icon\" href=\"/favicon.svg\" type=\"image/svg+xml\" />\n    <link rel=\"apple-touch-icon\" href=\"/apple-touch-icon.png\" />\n    <meta property=\"og:type\" content=\"website\" />\n    <meta property=\"og:site_name\" content=\"ESBE Incorporated\" />\n    <meta property=\"og:title\" content=\"Privacy Policy | ESBE Incorporated\" />\n    <meta property=\"og:description\" content=\"The ESBE Incorporated privacy policy: what we collect through esbeincorporated.org, how we use it, and your rights. Effective October 6, 2026.\" />\n    <meta property=\"og:url\" content=\"https://esbeincorporated.org/privacy\" />\n    <meta property=\"og:image\" content=\"https://esbeincorporated.org/og.svg\" />\n    <meta property=\"og:image:width\" content=\"1200\" />\n    <meta property=\"og:image:height\" content=\"630\" />\n    <meta name=\"twitter:card\" content=\"summary_large_image\" />\n    <meta name=\"twitter:title\" content=\"Privacy Policy | ESBE Incorporated\" />\n    <meta name=\"twitter:description\" content=\"The ESBE Incorporated privacy policy: what we collect through esbeincorporated.org, how we use it, and your rights. Effective October 6, 2026.\" />\n    <meta name=\"twitter:image\" content=\"https://esbeincorporated.org/og.svg\" />\n    <link rel=\"stylesheet\" href=\"/styles.css\" />\n    <title>Privacy Policy | ESBE Incorporated</title>\n    <script type=\"application/ld+json\">{\"@context\":\"https://schema.org\",\"@type\":\"NGO\",\"name\":\"ESBE Incorporated\",\"url\":\"https://esbeincorporated.org/\",\"taxID\":\"87-1218291\",\"email\":\"help@esbeincorporated.org\"}</script>\n  </head>\n  <body>\n    <a class=\"skip-link\" href=\"#main\">Skip to content</a>\n    <header class=\"site-header\">\n      <a class=\"wordmark\" href=\"/\" aria-label=\"ESBE Incorporated home\">ESBE <span>INC.</span></a>\n      <nav aria-label=\"Primary navigation\">\n        <a href=\"/about\">About</a><a href=\"/programs\">Programs</a><a href=\"/transparency\">Transparency</a><a href=\"/support\">Support</a><a href=\"/contact\">Contact</a>\n      </nav>\n      <a class=\"header-cta\" href=\"https://aivaclaims.com\" rel=\"noreferrer\">Visit AIVA Claims <span aria-hidden=\"true\">\u2197</span></a>\n    </header>\n    <main id=\"main\">\n<section class=\"hero\" aria-labelledby=\"hero-title\">\n        <p class=\"eyebrow\">PRIVACY POLICY</p>\n        <div class=\"hero-grid\">\n          <h1 id=\"hero-title\">Your information stays yours.</h1>\n          <div class=\"hero-copy\"><p>ESBE Incorporated respects your privacy. This policy explains what information we collect through esbeincorporated.org and how we use it. Effective date: October 6, 2026.</p></div>\n        </div>\n        <div class=\"hero-rule\" aria-hidden=\"true\"></div>\n      </section><section class=\"statement\" aria-labelledby=\"s1-title\">\n        <div><p class=\"section-mark\">01</p></div>\n        <div><p class=\"eyebrow\">INFORMATION WE COLLECT</p><h2 id=\"s1-title\">What we collect, and why.</h2></div>\n        <div><p class=\"body-large\">Information you provide: when you contact us by email or phone, we receive your name, contact information, and the contents of your message. If you seek claims assistance through AIVA Claims, you may share information about your military service and health conditions \u2014 this information is used solely to provide the assistance you requested.</p><p class=\"body-large\">Automatically collected information: like most websites, our hosting provider (Cloudflare) may log technical information such as IP addresses, browser type, and pages visited, for security and operational purposes. We do not use third-party advertising trackers.</p></div>\n      </section><section class=\"statement\" aria-labelledby=\"s2-title\">\n        <div><p class=\"section-mark\">02</p></div>\n        <div><p class=\"eyebrow\">HOW WE USE YOUR INFORMATION</p><h2 id=\"s2-title\">Limited, purposeful use.</h2></div>\n        <div><p class=\"body-large\">We use the information we collect to respond to your inquiries and provide requested services; to improve our programs and website; and to comply with legal obligations. We do not sell, rent, or share your personal information with third parties for marketing purposes.</p></div>\n      </section><section class=\"statement\" aria-labelledby=\"s3-title\">\n        <div><p class=\"section-mark\">03</p></div>\n        <div><p class=\"eyebrow\">DATA SECURITY</p><h2 id=\"s3-title\">Reasonable protection.</h2></div>\n        <div><p class=\"body-large\">We take reasonable measures to protect your information. Communications about VA claims may involve sensitive health information \u2014 we treat such communications with appropriate confidentiality. However, no internet transmission is completely secure, and you should never send highly sensitive documents over channels you don\u2019t trust.</p></div>\n      </section><section class=\"statement\" aria-labelledby=\"s4-title\">\n        <div><p class=\"section-mark\">04</p></div>\n        <div><p class=\"eyebrow\">YOUR RIGHTS</p><h2 id=\"s4-title\">Access, correction, deletion.</h2></div>\n        <div><p class=\"body-large\">You may request access to, correction of, or deletion of your personal information by contacting help@esbeincorporated.org. We will respond to verified requests within a reasonable time.</p></div>\n      </section><section class=\"statement\" aria-labelledby=\"s5-title\">\n        <div><p class=\"section-mark\">05</p></div>\n        <div><p class=\"eyebrow\">CHANGES & CONTACT</p><h2 id=\"s5-title\">This policy may change.</h2></div>\n        <div><p class=\"body-large\">We may update this policy periodically. The current version will always be posted at esbeincorporated.org/privacy, with its effective date noted above. Privacy questions: help@esbeincorporated.org or (802) 715-3723.</p></div>\n      </section>\n    </main>\n    <footer><div class=\"footer-brand\">ESBE INCORPORATED</div><p>ESBE Incorporated is a 501(c)(3) nonprofit organization, EIN 87-1218291. AIVA Claims is a charitable program of ESBE Incorporated. ESBE Tech is a separate for-profit technology company. ESBE Incorporated is not affiliated with or endorsed by the U.S. Department of Veterans Affairs.</p><div><span>\u00a9 2026 ESBE Incorporated</span><span><a href=\"/privacy\">Privacy</a> \u00b7 <a href=\"/contact\">Contact</a> \u00b7 <a href=\"/support\">Support</a></span></div></footer>\n    <script type=\"module\" src=\"/webmcp.js\"></script>\n  </body>\n</html>",
  "/contact": "<!doctype html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"utf-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n    <meta name=\"description\" content=\"Contact ESBE Incorporated: help@esbeincorporated.org, (802) 715-3723, 1070 Bridgeview Way #1010, San Francisco, CA 94158.\" />\n    <meta name=\"theme-color\" content=\"#12352d\" />\n    <link rel=\"canonical\" href=\"https://esbeincorporated.org/contact\" />\n    <link rel=\"icon\" href=\"/favicon.ico\" type=\"image/x-icon\" />\n    <link rel=\"icon\" href=\"/favicon.svg\" type=\"image/svg+xml\" />\n    <link rel=\"apple-touch-icon\" href=\"/apple-touch-icon.png\" />\n    <meta property=\"og:type\" content=\"website\" />\n    <meta property=\"og:site_name\" content=\"ESBE Incorporated\" />\n    <meta property=\"og:title\" content=\"Contact Us | ESBE Incorporated\" />\n    <meta property=\"og:description\" content=\"Contact ESBE Incorporated: help@esbeincorporated.org, (802) 715-3723, 1070 Bridgeview Way #1010, San Francisco, CA 94158.\" />\n    <meta property=\"og:url\" content=\"https://esbeincorporated.org/contact\" />\n    <meta property=\"og:image\" content=\"https://esbeincorporated.org/og.svg\" />\n    <meta property=\"og:image:width\" content=\"1200\" />\n    <meta property=\"og:image:height\" content=\"630\" />\n    <meta name=\"twitter:card\" content=\"summary_large_image\" />\n    <meta name=\"twitter:title\" content=\"Contact Us | ESBE Incorporated\" />\n    <meta name=\"twitter:description\" content=\"Contact ESBE Incorporated: help@esbeincorporated.org, (802) 715-3723, 1070 Bridgeview Way #1010, San Francisco, CA 94158.\" />\n    <meta name=\"twitter:image\" content=\"https://esbeincorporated.org/og.svg\" />\n    <link rel=\"stylesheet\" href=\"/styles.css\" />\n    <title>Contact Us | ESBE Incorporated</title>\n    <script type=\"application/ld+json\">{\"@context\":\"https://schema.org\",\"@type\":\"NGO\",\"name\":\"ESBE Incorporated\",\"url\":\"https://esbeincorporated.org/\",\"taxID\":\"87-1218291\",\"email\":\"help@esbeincorporated.org\"}</script>\n  </head>\n  <body>\n    <a class=\"skip-link\" href=\"#main\">Skip to content</a>\n    <header class=\"site-header\">\n      <a class=\"wordmark\" href=\"/\" aria-label=\"ESBE Incorporated home\">ESBE <span>INC.</span></a>\n      <nav aria-label=\"Primary navigation\">\n        <a href=\"/about\">About</a><a href=\"/programs\">Programs</a><a href=\"/transparency\">Transparency</a><a href=\"/support\">Support</a><a href=\"/contact\">Contact</a>\n      </nav>\n      <a class=\"header-cta\" href=\"https://aivaclaims.com\" rel=\"noreferrer\">Visit AIVA Claims <span aria-hidden=\"true\">\u2197</span></a>\n    </header>\n    <main id=\"main\">\n<section class=\"hero\" aria-labelledby=\"hero-title\">\n        <p class=\"eyebrow\">CONTACT US</p>\n        <div class=\"hero-grid\">\n          <h1 id=\"hero-title\">Get in touch.</h1>\n          <div class=\"hero-copy\"><p>We welcome inquiries about our programs, partnership opportunities, governance, and press. The fastest way to reach us is email \u2014 every message is read by a real person.</p></div>\n        </div>\n        <div class=\"hero-rule\" aria-hidden=\"true\"></div>\n      </section><section class=\"contact\" aria-labelledby=\"contact-title\">\n        <div><p class=\"section-mark\">01</p></div>\n        <div><p class=\"eyebrow\">PUBLIC CONTACT</p><h2 id=\"contact-title\">Contact ESBE Incorporated.</h2><p class=\"contact-copy\">For public inquiries, governance requests, and nonprofit correspondence.</p><div class=\"contact-details\"><a class=\"contact-email\" href=\"mailto:help@esbeincorporated.org\">help@esbeincorporated.org <span aria-hidden=\"true\">\u2197</span></a><a class=\"contact-phone\" href=\"tel:+18027153723\">(802) 715-3723</a><address>1070 Bridgeview Way #1010<br />San Francisco, CA 94158</address></div></div>\n      </section><section class=\"statement\" aria-labelledby=\"s2-title\">\n        <div><p class=\"section-mark\">02</p></div>\n        <div><p class=\"eyebrow\">FOR VETERANS SEEKING CLAIMS HELP</p><h2 id=\"s2-title\">Start with AIVA Claims.</h2></div>\n        <div><p class=\"body-large\">If you are a veteran who needs help with a VA disability claim, contact AIVA Claims directly at aivaclaims.com \u2014 or email help@esbeincorporated.org with the subject line \u201cClaims Help\u201d and tell us briefly what you\u2019re working on. Our assistance is free: we never charge fees or take a percentage of your benefits. Please don\u2019t include sensitive medical records in your first message; we\u2019ll tell you exactly what we need and the safest way to share it.</p></div>\n      </section><section class=\"statement\" aria-labelledby=\"s3-title\">\n        <div><p class=\"section-mark\">03</p></div>\n        <div><p class=\"eyebrow\">FOR GOVERNANCE & NONPROFIT CORRESPONDENCE</p><h2 id=\"s3-title\">Formal inquiries welcome.</h2></div>\n        <div><p class=\"body-large\">For questions about our nonprofit status, finances, governance, or partnerships, email help@esbeincorporated.org with the subject line \u201cGovernance.\u201d Members of the press covering our programs or civic access projects can use the same address with the subject line \u201cPress.\u201d</p></div>\n      </section><section class=\"statement\" aria-labelledby=\"s4-title\">\n        <div><p class=\"section-mark\">04</p></div>\n        <div><p class=\"eyebrow\">WHAT TO INCLUDE IN YOUR MESSAGE</p><h2 id=\"s4-title\">Help us help you faster.</h2></div>\n        <div><p class=\"body-large\">You don\u2019t need to write a formal letter \u2014 a few clear sentences are perfect. Tell us who you are, what you\u2019re asking about, and the best way to reach you. If your question is about a specific program, name it: AIVA Claims, one of the civic access projects, or a governance matter.</p><p class=\"body-large\">A note on sensitive information: please don\u2019t attach medical records, DD-214s, or other sensitive documents to your first message. If we need documents, we\u2019ll tell you exactly what\u2019s needed and the safest way to share them. Email is convenient, but no internet transmission is completely secure \u2014 we\u2019d rather guide you to a safer channel than have you overshare up front.</p></div>\n      </section><section class=\"statement\" aria-labelledby=\"s5-title\">\n        <div><p class=\"section-mark\">05</p></div>\n        <div><p class=\"eyebrow\">MAIL</p><h2 id=\"s5-title\">Prefer paper?</h2></div>\n        <div><p class=\"body-large\">If you\u2019re sending documents or formal correspondence by mail, address it to: ESBE Incorporated, 1070 Bridgeview Way #1010, San Francisco, CA 94158. For time-sensitive matters, email is faster \u2014 mail is checked less frequently than our inbox.</p></div>\n      </section>\n    </main>\n    <footer><div class=\"footer-brand\">ESBE INCORPORATED</div><p>ESBE Incorporated is a 501(c)(3) nonprofit organization, EIN 87-1218291. AIVA Claims is a charitable program of ESBE Incorporated. ESBE Tech is a separate for-profit technology company. ESBE Incorporated is not affiliated with or endorsed by the U.S. Department of Veterans Affairs.</p><div><span>\u00a9 2026 ESBE Incorporated</span><span><a href=\"/privacy\">Privacy</a> \u00b7 <a href=\"/contact\">Contact</a> \u00b7 <a href=\"/support\">Support</a></span></div></footer>\n    <script type=\"module\" src=\"/webmcp.js\"></script>\n  </body>\n</html>",
  "/support": "<!doctype html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"utf-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n    <meta name=\"description\" content=\"Support free VA disability claims assistance for veterans. ESBE Incorporated is a 501(c)(3) nonprofit (EIN 87-1218291); donations are tax-deductible.\" />\n    <meta name=\"theme-color\" content=\"#12352d\" />\n    <link rel=\"canonical\" href=\"https://esbeincorporated.org/support\" />\n    <link rel=\"icon\" href=\"/favicon.ico\" type=\"image/x-icon\" />\n    <link rel=\"icon\" href=\"/favicon.svg\" type=\"image/svg+xml\" />\n    <link rel=\"apple-touch-icon\" href=\"/apple-touch-icon.png\" />\n    <meta property=\"og:type\" content=\"website\" />\n    <meta property=\"og:site_name\" content=\"ESBE Incorporated\" />\n    <meta property=\"og:title\" content=\"Support Our Mission | ESBE Incorporated\" />\n    <meta property=\"og:description\" content=\"Support free VA disability claims assistance for veterans. ESBE Incorporated is a 501(c)(3) nonprofit (EIN 87-1218291); donations are tax-deductible.\" />\n    <meta property=\"og:url\" content=\"https://esbeincorporated.org/support\" />\n    <meta property=\"og:image\" content=\"https://esbeincorporated.org/og.svg\" />\n    <meta property=\"og:image:width\" content=\"1200\" />\n    <meta property=\"og:image:height\" content=\"630\" />\n    <meta name=\"twitter:card\" content=\"summary_large_image\" />\n    <meta name=\"twitter:title\" content=\"Support Our Mission | ESBE Incorporated\" />\n    <meta name=\"twitter:description\" content=\"Support free VA disability claims assistance for veterans. ESBE Incorporated is a 501(c)(3) nonprofit (EIN 87-1218291); donations are tax-deductible.\" />\n    <meta name=\"twitter:image\" content=\"https://esbeincorporated.org/og.svg\" />\n    <link rel=\"stylesheet\" href=\"/styles.css\" />\n    <title>Support Our Mission | ESBE Incorporated</title>\n    <script type=\"application/ld+json\">{\"@context\":\"https://schema.org\",\"@type\":\"NGO\",\"name\":\"ESBE Incorporated\",\"url\":\"https://esbeincorporated.org/\",\"taxID\":\"87-1218291\",\"email\":\"help@esbeincorporated.org\"}</script>\n  </head>\n  <body>\n    <a class=\"skip-link\" href=\"#main\">Skip to content</a>\n    <header class=\"site-header\">\n      <a class=\"wordmark\" href=\"/\" aria-label=\"ESBE Incorporated home\">ESBE <span>INC.</span></a>\n      <nav aria-label=\"Primary navigation\">\n        <a href=\"/about\">About</a><a href=\"/programs\">Programs</a><a href=\"/transparency\">Transparency</a><a href=\"/support\">Support</a><a href=\"/contact\">Contact</a>\n      </nav>\n      <a class=\"header-cta\" href=\"https://aivaclaims.com\" rel=\"noreferrer\">Visit AIVA Claims <span aria-hidden=\"true\">\u2197</span></a>\n    </header>\n    <main id=\"main\">\n<section class=\"hero\" aria-labelledby=\"hero-title\">\n        <p class=\"eyebrow\">SUPPORT OUR MISSION</p>\n        <div class=\"hero-grid\">\n          <h1 id=\"hero-title\">Free for veterans, funded by people who believe in the mission.</h1>\n          <div class=\"hero-copy\"><p>Every veteran AIVA Claims helps receives our assistance for free \u2014 no fees, no percentage of back pay, no strings. Your support directly funds the time, tools, and technology that make free claims help possible.</p></div>\n        </div>\n        <div class=\"hero-rule\" aria-hidden=\"true\"></div>\n      </section><section class=\"statement\" aria-labelledby=\"s1-title\">\n        <div><p class=\"section-mark\">01</p></div>\n        <div><p class=\"eyebrow\">WHY YOUR SUPPORT MATTERS</p><h2 id=\"s1-title\">What donations make possible.</h2></div>\n        <div><p class=\"body-large\">Preparing a VA disability claim well takes real work: understanding rating criteria, gathering medical evidence, preparing for examinations, and navigating appeals when claims are denied. AIVA Claims does that work alongside veterans for free \u2014 which means someone has to fund the people and systems behind it.</p><p class=\"body-large\">Donations to ESBE Incorporated keep AIVA Claims free for every veteran who needs it, and sustain the civic access projects \u2014 ImproveBayArea, Hospital Ledger, the Treasure Island power tracker, and others \u2014 that make public systems more understandable for everyone.</p></div>\n      </section><section class=\"statement\" aria-labelledby=\"s2-title\">\n        <div><p class=\"section-mark\">02</p></div>\n        <div><p class=\"eyebrow\">HOW TO DONATE</p><h2 id=\"s2-title\">Talk to us first.</h2></div>\n        <div><p class=\"body-large\">We are currently setting up online giving. If you\u2019d like to support our work, email help@esbeincorporated.org with the subject line \u201cDonation\u201d and we\u2019ll get back to you with the current options.</p><p class=\"body-large\">ESBE Incorporated is a 501(c)(3) nonprofit organization (EIN 87-1218291). Donations are tax-deductible to the extent allowed by law. Consult your tax advisor.</p></div>\n      </section><section class=\"statement\" aria-labelledby=\"s3-title\">\n        <div><p class=\"section-mark\">03</p></div>\n        <div><p class=\"eyebrow\">OTHER WAYS TO SUPPORT</p><h2 id=\"s3-title\">Money isn\u2019t the only way.</h2></div>\n        <div><p class=\"body-large\">Spread the word: share aivaclaims.com with veterans who might need help. Many veterans don\u2019t know free claims assistance exists \u2014 a single share can change someone\u2019s outcome.</p><p class=\"body-large\">Partner with us: if your organization serves veterans, contact us at help@esbeincorporated.org about partnership opportunities \u2014 from referral relationships to joint outreach.</p></div>\n      </section>\n    </main>\n    <footer><div class=\"footer-brand\">ESBE INCORPORATED</div><p>ESBE Incorporated is a 501(c)(3) nonprofit organization, EIN 87-1218291. AIVA Claims is a charitable program of ESBE Incorporated. ESBE Tech is a separate for-profit technology company. ESBE Incorporated is not affiliated with or endorsed by the U.S. Department of Veterans Affairs.</p><div><span>\u00a9 2026 ESBE Incorporated</span><span><a href=\"/privacy\">Privacy</a> \u00b7 <a href=\"/contact\">Contact</a> \u00b7 <a href=\"/support\">Support</a></span></div></footer>\n    <script type=\"module\" src=\"/webmcp.js\"></script>\n  </body>\n</html>"
};
