const SITEMAP_XML = "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<urlset xmlns=\"http://www.sitemaps.org/schemas/sitemap/0.9\">\n  <url><loc>https://esbeincorporated.org/</loc><lastmod>2026-10-06</lastmod><changefreq>monthly</changefreq></url>\n  <url><loc>https://esbeincorporated.org/about</loc><lastmod>2026-10-06</lastmod><changefreq>monthly</changefreq></url>\n  <url><loc>https://esbeincorporated.org/programs</loc><lastmod>2026-10-06</lastmod><changefreq>monthly</changefreq></url>\n  <url><loc>https://esbeincorporated.org/transparency</loc><lastmod>2026-10-06</lastmod><changefreq>monthly</changefreq></url>\n  <url><loc>https://esbeincorporated.org/privacy</loc><lastmod>2026-10-06</lastmod><changefreq>monthly</changefreq></url>\n  <url><loc>https://esbeincorporated.org/contact</loc><lastmod>2026-10-06</lastmod><changefreq>monthly</changefreq></url>\n  <url><loc>https://esbeincorporated.org/support</loc><lastmod>2026-10-06</lastmod><changefreq>monthly</changefreq></url>\n</urlset>";
const ROBOTS_TXT = "User-agent: *\nAllow: /\nSitemap: https://esbeincorporated.org/sitemap.xml\n";
const FAVICON_ICO_B64 = "";
const APPLE_TOUCH_B64 = "";
const STATIC_ASSETS = {
  "/styles.css": ["text/css; charset=utf-8", ""],
  "/tokens.css": ["text/css; charset=utf-8", ""],
  "/favicon.svg": ["image/svg+xml", ""],
  "/og.svg": ["image/svg+xml", ""],
  "/webmcp.js": ["application/javascript; charset=utf-8", ""],
  "/.well-known/security.txt": ["text/plain; charset=utf-8", "Q29udGFjdDogbWFpbHRvOnNlY3VyaXR5QGVzYmVpbmNvcnBvcmF0ZWQub3JnCkV4cGlyZXM6IDIwMjctMDktMjRUMDA6MDA6MDBaClByZWZlcnJlZC1MYW5ndWFnZXM6IGVuCg=="]
};

function b64bytes(b64) {
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

const SEC_HEADERS = {
  "Content-Security-Policy": "default-src 'self'; base-uri 'self'; connect-src 'self' https://cloudflareinsights.com; font-src 'self' https://fonts.gstatic.com; frame-ancestors 'none'; img-src 'self' data:; object-src 'none'; script-src 'self' https://static.cloudflareinsights.com; style-src 'self' 'unsafe-inline' https://fonts.googleapis.com; upgrade-insecure-requests",
  "Referrer-Policy": "strict-origin-when-cross-origin",
  "Strict-Transport-Security": "max-age=63072000; includeSubDomains; preload",
  "X-Content-Type-Options": "nosniff",
  "X-Frame-Options": "DENY",
  "Cross-Origin-Opener-Policy": "same-origin",
  "Cross-Origin-Resource-Policy": "same-origin"
};

function withSec(res) {
  const h = new Headers(res.headers);
  for (const [k, v] of Object.entries(SEC_HEADERS)) h.set(k, v);
  return new Response(res.body, { status: res.status, statusText: res.statusText, headers: h });
}

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    if (url.hostname === "www.esbeincorporated.org") {
      return Response.redirect("https://esbeincorporated.org" + url.pathname + url.search, 301);
    }
    let path = url.pathname;
    if (path.length > 1 && path.endsWith("/")) path = path.slice(0, -1);

    let res;
    if (path === "/security.txt") {
      return Response.redirect("https://esbeincorporated.org/.well-known/security.txt", 302);
    } else if (path === "/favicon.ico") {
      res = new Response(b64bytes(FAVICON_ICO_B64), { headers: { "Content-Type": "image/x-icon", "Cache-Control": "public, max-age=86400" } });
    } else if (path === "/apple-touch-icon.png" || path === "/apple-touch-icon-precomposed.png") {
      res = new Response(b64bytes(APPLE_TOUCH_B64), { headers: { "Content-Type": "image/png", "Cache-Control": "public, max-age=86400" } });
    } else if (path === "/sitemap.xml") {
      res = new Response(SITEMAP_XML, { headers: { "Content-Type": "application/xml; charset=utf-8", "Cache-Control": "public, max-age=3600" } });
    } else if (path === "/robots.txt") {
      res = new Response(ROBOTS_TXT, { headers: { "Content-Type": "text/plain; charset=utf-8" } });
    } else if (PAGES[path]) {
      res = new Response(PAGES[path], { headers: { "Content-Type": "text/html; charset=utf-8", "Cache-Control": "public, max-age=300" } });
    } else if (STATIC_ASSETS[path]) {
      const [ct, b64] = STATIC_ASSETS[path];
      res = new Response(b64bytes(b64), { headers: { "Content-Type": ct, "Cache-Control": "public, max-age=86400" } });
    } else {
      res = new Response(NOTFOUND_HTML, { status: 404, headers: { "Content-Type": "text/html; charset=utf-8" } });
    }
    return withSec(res);
  }
};
